if (n < N_THRESHOLD || alpha_squared < 10 * n) {
    // Use exact calculation for small n
    double logFactorial = 0;
    for (unsigned long i = 1; i <= n; ++i) {
        logFactorial += std::log(static_cast<double>(i));
    }
    const dcomp alpha_n = std::pow(alpha, n);
    const double sqrt_factorial = std::exp(-0.5 * logFactorial);
    return alpha_n * sqrt_factorial;
} else {
    // Use Stirling's approximation for large n
    const double log_n = std::log(n);
    const double stirling_log_factorial = n * log_n - n + 0.5 * std::log(2 * PI * n);
